style.css:
/* Oudroze & Donkergrijs — Global Style */
/* i really want this to be global */

:root {
  /* Pas de kleuren gerust aan */
  --my-pink: #b98291;
  --my-dark: #29272b;
  --my-text: #e8dfe2;
}

/* donkere achtergrond en lichte tekst */
body {
  background-color: var(--my-dark) !important;
  color: var(--my-text) !important;
}

/* oudroze links */
a,
a:visited {
  color: var(--my-pink) !important;
}

/* oudroze bij aanwijzen */
a:hover {
  color: #d5a3b0 !important;
}

/* geselecteerde tekst */
::selection {
  background: var(--my-pink) !important;
  color: #29272b !important;
}
